query TemplateLifecycleManagement($templateId: ID, $operation: LifecycleOperation!) {
  templateLifecycle(templateId: $templateId, operation: $operation) {
    template {
      id
      identifier
      name
      version
      status
      createdAt
      updatedAt
      lastUsedAt
      usageCount
    }
    lifecycle {
      currentStage
      possibleTransitions
      history {
        stage
        timestamp
        performedBy
        reason
      }
    }
    dependencies {
      dependsOn {
        id
        identifier
        name
        relationship
      }
      dependentTemplates {
        id
        identifier
        name
        relationship
      }
    }
    analytics {
      usageStats {
        totalExecutions
        successRate
        avgExecutionTime
        lastWeekUsage
        popularVariables
      }
      performance {
        complexity
        executionTrend
        errorPatterns
      }
    }
    recommendations {
      optimization
      archiving
      deprecation
      migration
    }
  }
}
